import sys; sys.path.insert(0, __import__("os").path.join(__import__("os").path.dirname(__file__), "..", "..", "pipeline"))
from scriptkit import sc, ch, save, S

# Grandma Ruth 108 · Everyday recipe: American goulash (macaroni and beef)

sc("""Sweetheart, American goulash is the supper that fed half the families in this country for seventy years. Elbow macaroni, ground beef, and tomatoes, all in one pot, rich and saucy and ready in thirty minutes. But most of the goulash I taste is watery and bland, or the macaroni is swollen and mushy. And it's always the same five mistakes. Every one is easy to fix.""",
   "pot of American goulash macaroni beef", "WATERY AND BLAND")
sc("""So tonight I'm giving you the goulash my mother made every Thursday on Elm Street, step by step. And stay with me, because the last secret is one little thing from the spice cabinet that she stirred in at the very end, and it's why the neighbor kids always seemed to show up at our back door on Thursdays.""",
   "children at back door kitchen 1950s", "THURSDAY NIGHTS")

ch("Not really goulash")
sc("""First, honey, I have to confess something. American goulash isn't really goulash at all. Real goulash comes from Hungary. It's a slow-cooked beef stew with lots of paprika and no pasta at all. Hungarian cowherds made it in big kettles over open fires, hundreds of years ago. The word gulyás even means herdsman. In a minute I'll tell you how it turned into macaroni in America.""",
   "Hungarian goulash kettle over open fire", "IT'S HUNGARIAN")
sc("""When Hungarian families came to America, they brought the name. And American home cooks, especially during the Depression, took that name and put it on whatever they could make cheaply in one pot. Macaroni was cheap. Canned tomatoes were cheap. A pound of ground beef could feed six. By the nineteen fifties, goulash was in every school cafeteria and church cookbook in the Midwest. Some people call it chili mac or slumgullion. In our house, it was goulash.""",
   "1950s school cafeteria lunch tray", "SLUMGULLION")
sc("""Thursday was the night before payday, honey. The icebox was nearly empty by Thursday. So my mother made goulash, because all it took was a pound of beef, a box of macaroni, and a couple of cans from the pantry. And somehow, every Thursday, there were one or two extra children at our table. The Kowalski boys from next door. My mother never said a word. She just added another cup of macaroni.""",
   "family supper table with extra children", "ANOTHER CUP OF MACARONI")

sc("""Those boys were seven and nine, honey, and their father worked nights at the foundry. Their mother cleaned houses during the day. So on Thursdays, by suppertime, there was usually nobody home and nothing in their icebox either. The first time they came, they just stood at the screen door, sniffing. My mother opened it and said, well, don't let the flies in. Come wash your hands. I'll tell you how she got paid back in a minute.""",
   "two boys standing at screen door 1950s", "DON'T LET THE FLIES IN")
ch("What you need")
sc("""Here's what you need for six people. One and a half pounds of ground beef. One big onion, chopped. One green bell pepper, chopped. Three cloves of garlic. One can of crushed tomatoes, twenty-eight ounces. One can of tomato sauce, fifteen ounces. Two tablespoons of tomato paste. Two cups of beef broth. And two cups of dry elbow macaroni.""",
   "goulash ingredients on kitchen counter", "WHAT YOU NEED")
sc("""For seasoning, a tablespoon of paprika, a teaspoon of Italian seasoning, a tablespoon of Worcestershire sauce, two bay leaves, a teaspoon of salt, and half a teaspoon of pepper. And a cup of shredded sharp cheddar for the top, if you like. Plus the secret ingredient, which I'll tell you at the end. Most of it you probably already have in your pantry right now, honey. That's the whole beauty of it.""",
   "spice jars paprika bay leaves", "ALREADY IN YOUR PANTRY")

sc("""About the macaroni, sweetheart. Use plain elbow macaroni, the cheap kind. Don't use fancy pasta, and don't use the little shells, because they trap too much sauce and go soft. And don't cook the macaroni separately in a pot of water, the way some recipes say. That's the lazy way, and it makes a watery goulash, because the pasta never drinks up any of that tomato flavor. One pot, honey. Always one pot.""",
   "box of elbow macaroni on counter", "ALWAYS ONE POT")
ch("Mistake one and two")
sc("""Mistake number one is gray, steamed beef. People dump the meat in a cold pot, all at once, and stir it constantly, and it turns gray and boils in its own juice. No flavor. Get your big pot good and hot first. Put the beef in, press it flat, and leave it alone for four or five minutes, until the bottom gets a dark brown crust. Then break it up. That brown is where the flavor is.""",
   "ground beef browning in pot", "LEAVE IT ALONE")
sc("""If Grandma's recipe is helping you, tap the like button for me, sweetheart. It helps more people find these videos. Mistake number two is not draining the fat. Goulash should be rich, not greasy. Once the beef is browned, spoon off most of the fat, leaving about a tablespoon. Then add your onion and green pepper, and cook them five minutes until soft. Add the garlic for the last minute, so it doesn't burn.""",
   "spooning fat out of pot of beef", "RICH, NOT GREASY")

ch("Mistake three")
sc("""Mistake number three is forgetting to cook the tomato paste. Most people stir it straight into the liquid, and it tastes raw and tinny. Push the beef and vegetables to the side, put the tomato paste right on the hot bottom of the pot, and let it sizzle for a minute or two, until it turns a darker, brick red. Then add the paprika and stir it into the paste for thirty seconds. That wakes the paprika up.""",
   "tomato paste caramelizing in pot", "BRICK RED")
sc("""Now add the crushed tomatoes, the tomato sauce, the broth, the Worcestershire, the Italian seasoning, the bay leaves, salt, and pepper. Stir it all together, scraping up every brown bit from the bottom of the pot. Bring it to a simmer, put a lid on, and let it cook gently for fifteen minutes before the macaroni ever goes in. In a minute I'll tell you why that waiting matters.""",
   "goulash sauce simmering in pot", "SCRAPE THE BOTTOM")

ch("Mistake four and five")
sc("""So far, browned beef, no grease, and tomato paste cooked until it's brick red. Mistake number four is adding the macaroni too early. If the macaroni cooks the whole time, it turns soft and swollen. The sauce needs those fifteen minutes on its own to get rich and deep. Only then do you stir in the dry macaroni, right into the sauce. It cooks in the sauce and soaks up all that flavor.""",
   "dry elbow macaroni stirred into sauce", "MACARONI GOES IN LAST")
sc("""Mistake number five is cooking the macaroni until it's soft. Cover the pot, keep it at a gentle simmer, and stir every few minutes so it doesn't stick. Start tasting at about eight minutes. Take it off the heat when the macaroni still has a little bite in the middle, honey. It keeps cooking in the hot sauce. If you wait until it's soft in the pot, it'll be mush on the plate.""",
   "spoon tasting macaroni from pot", "STILL A LITTLE BITE")
sc("""If it looks too thick, add a splash of broth. If it looks too thin, leave the lid off for a few minutes, and it'll tighten right up. Pull out the bay leaves. And let it sit for five minutes off the heat before you serve it. Stay with me, because now comes my mother's Thursday secret.""",
   "thick saucy goulash resting off heat", "LET IT SIT")

sc("""Now, about the cheese. Don't stir the cheddar into the whole pot, honey, or the leftovers turn stringy and greasy. Put it on each bowl, right before you serve it, so it melts on top from the heat of the goulash. And use real sharp cheddar that you shred yourself. The bagged kind is coated in powder so it won't clump, and it never melts right.""",
   "shredding block of cheddar cheese", "SHRED IT YOURSELF")
ch("The secret")
sc("""Here's my mother's secret, sweetheart. At the very end, after the bay leaves came out, she stirred in one teaspoon of sugar and one teaspoon of apple cider vinegar. That's all. The sugar takes away the tinny, sour edge of canned tomatoes. The vinegar wakes everything up, so it doesn't taste flat. You won't taste either one. But you'll taste the difference, honey. It goes from cafeteria to Sunday dinner.""",
   "teaspoon of sugar and vinegar over pot", "SUGAR AND VINEGAR")
sc("""She learned it from Mrs. Kowalski next door, the mother of those two boys who showed up every Thursday. She was from the old country, and she said every good tomato dish needs a little sweet and a little sour. So it was a trade, you see. Mrs. Kowalski gave my mother the secret, and my mother fed her boys every Thursday for ten years. Nobody ever mentioned it. That's how neighbors worked back then.""",
   "two neighbor women talking over fence 1950s", "THAT'S HOW NEIGHBORS WORKED")

ch("Make it your own")
sc("""Serve it in bowls with a handful of sharp cheddar melted on top, and a slice of buttered bread on the side to wipe the bowl clean. Some families add a can of corn or kidney beans. Some add a pinch of chili powder. Harold liked his with a shake of hot sauce. Leftovers are even better the next day, honey. Add a splash of water when you reheat it, because the macaroni drinks up the sauce overnight.""",
   "bowl of goulash with melted cheddar and bread", "EVEN BETTER TOMORROW")
sc("""The Kowalski boys grew up, sweetheart. One of them became a pharmacist in town, and when I went in to pick up Harold's medicine, the year he was sick, he wouldn't let me pay. I said, Stanley, what are you doing? He said, Mrs. Ruth, your mother fed me goulash every Thursday for ten years. I'm just catching up. I cried right there at the counter.""",
   "pharmacist at counter small town pharmacy", "JUST CATCHING UP")

ch("Grandma's kitchen")
sc("""Make it this week, sweetheart, and set out an extra bowl, just in case. Tell me in the comments, what did your family call this dish? Goulash, chili mac, or something else? There are more of my everyday recipes in the playlist right there on your screen. Good night, honey.""",
   "pot of goulash on stove with bowls", "WHAT DID YOU CALL IT?")

for s in S:
    s["cuts"], s["moves"] = 4, True

save("grandma108", "American Goulash EVERYONE's Grandma Made (Why Yours Is WATERY)",
     ["Grandma Ruth is a narrated character built from real memories and records of the era.",
      "Hungarian gulyás is a paprika beef stew named after herdsmen; the American macaroni-and-beef 'goulash' is an unrelated one-pot dish popular from the Depression through the 1950s.",
      "Recipe as written by Grandma Ruth: 1 1/2 lb ground beef, onion, green pepper, 3 garlic cloves, 28 oz crushed tomatoes, 15 oz tomato sauce, 2 tbsp tomato paste, 2 cups beef broth, 2 cups elbow macaroni, 1 tbsp paprika, 1 tsp Italian seasoning, 1 tbsp Worcestershire, 2 bay leaves, salt, pepper, 1 tsp sugar, 1 tsp cider vinegar."],
     "everyday recipe", minutes=(10, 14.5), voice="en_US-lessac-high")
